import React, { useEffect, useId, useMemo, useRef, useState } from "react"
import { Checkbox, Delta, Icon, SegmentedControl, TickerMark } from "../ui"
import { COMPANIES, getCompany } from "../../data/companies"
import { getSessionChange } from "../../data/markets"

/**
 * LeftRail — the control column of the /technical workspace.
 *
 * Five stacked blocks: the ticker combobox, the timeframe picker, the indicator
 * list, the chart style picker and the update button. Every control is fully
 * controlled by the page; this component owns no chart state, only the transient
 * UI state that has no business leaving it — the search query, whether the menu
 * is open, and which EMA period popover is showing.
 *
 * SSR: nothing here reads window, document or localStorage at module scope or
 * during render. The document listeners live inside useEffect and are removed on
 * cleanup, so Gatsby's build-time Node render is untouched.
 */

const TIMEFRAMES = ["1D", "5D", "1M", "3M", "6M", "1Y", "5Y"]

const CHART_STYLES = [
  { label: "Candlestick", value: "candlestick" },
  { label: "Line", value: "line" },
  { label: "Area", value: "area" },
]

/**
 * The indicator list, in render order. A "ema" row carries a period the user can
 * edit; a "flag" row is a plain boolean. `swatch` is a var() reference, never a
 * literal colour — tokens.css owns every value.
 */
const INDICATOR_ROWS = [
  { key: "volume", kind: "flag", label: "Volume", swatch: null },
  { key: "vwap", kind: "flag", label: "VWAP", swatch: "var(--chart-vwap)" },
  { key: "ema9", kind: "ema", defaultPeriod: 9, swatch: "var(--chart-ema9)" },
  { key: "ema20", kind: "ema", defaultPeriod: 20, swatch: "var(--chart-ema20)" },
  { key: "ema50", kind: "ema", defaultPeriod: 50, swatch: "var(--chart-ema50)" },
  { key: "ema200", kind: "ema", defaultPeriod: 200, swatch: "var(--chart-ema200)" },
  { key: "rsi", kind: "flag", label: "RSI", swatch: null },
  { key: "macd", kind: "flag", label: "MACD", swatch: null },
]

const MIN_PERIOD = 2
const MAX_PERIOD = 400

// Buttons that must span the rail. Geometry only — no colour lives in JS.
const FULL_WIDTH = { width: "100%" }

function filterCompanies(query) {
  const q = String(query || "").trim().toLowerCase()
  if (!q) return COMPANIES
  return COMPANIES.filter(
    company =>
      company.symbol.toLowerCase().indexOf(q) !== -1 ||
      company.name.toLowerCase().indexOf(q) !== -1
  )
}

function money(value) {
  return value === null || value === undefined || !Number.isFinite(value)
    ? "—"
    : "$" + value.toFixed(2)
}

/** Reads one EMA entry defensively, so a malformed config never yields NaN. */
function readEma(config, key, defaultPeriod) {
  const entry = config ? config[key] : null
  if (entry && typeof entry === "object") {
    return {
      on: !!entry.on,
      period: Number.isFinite(entry.period) ? entry.period : defaultPeriod,
    }
  }
  return { on: false, period: defaultPeriod }
}

export default function LeftRail({
  symbol,
  onSymbolChange,
  timeframe,
  onTimeframeChange,
  indicators,
  onIndicatorsChange,
  chartStyle,
  onChartStyleChange,
  onUpdate,
}) {
  const [query, setQuery] = useState("")
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(-1)
  const [periodKey, setPeriodKey] = useState(null)
  const [draftPeriod, setDraftPeriod] = useState("")

  const pickerRef = useRef(null)
  const listRef = useRef(null)
  const optionRefs = useRef([])
  const periodInputRef = useRef(null)

  const baseId = useId()
  const inputId = "picker-input-" + baseId
  const listId = "picker-list-" + baseId
  const popId = "indicator-pop-" + baseId
  const optionId = index => "picker-option-" + baseId + "-" + index

  const matches = useMemo(() => filterCompanies(query), [query])
  const hasMatches = matches.length > 0
  // The highlight is derived, so a shrinking result set can never leave it
  // pointing past the end of the list.
  const active = activeIndex >= 0 && activeIndex < matches.length ? activeIndex : -1
  const menuOpen = open && hasMatches

  const company = getCompany(symbol)
  const session = getSessionChange(symbol)

  /* ----- combobox -------------------------------------------------------- */

  function closeMenu() {
    setOpen(false)
    setActiveIndex(-1)
  }

  function selectSymbol(next) {
    if (next && typeof onSymbolChange === "function") onSymbolChange(next)
    setQuery("")
    closeMenu()
  }

  function handleQueryChange(event) {
    const value = event.target.value
    setQuery(value)
    setOpen(true)
    // Highlight the first hit as you type, so Enter always does the obvious thing.
    setActiveIndex(filterCompanies(value).length > 0 ? 0 : -1)
  }

  function handleInputKeyDown(event) {
    const last = matches.length - 1

    if (event.key === "ArrowDown") {
      event.preventDefault()
      setOpen(true)
      if (!hasMatches) return
      setActiveIndex(active === -1 || active === last ? 0 : active + 1)
      return
    }
    if (event.key === "ArrowUp") {
      event.preventDefault()
      setOpen(true)
      if (!hasMatches) return
      setActiveIndex(active <= 0 ? last : active - 1)
      return
    }
    if (event.key === "Enter") {
      if (menuOpen && active >= 0) {
        event.preventDefault()
        selectSymbol(matches[active].symbol)
      }
      return
    }
    if (event.key === "Escape") {
      event.preventDefault()
      closeMenu()
      return
    }
    if (event.key === "Tab") {
      closeMenu()
    }
  }

  // Outside click closes the menu. Attached here, never at module scope.
  useEffect(() => {
    if (!open) return undefined

    function onPointerDown(event) {
      if (pickerRef.current && !pickerRef.current.contains(event.target)) {
        setOpen(false)
        setActiveIndex(-1)
      }
    }

    document.addEventListener("mousedown", onPointerDown)
    return () => {
      document.removeEventListener("mousedown", onPointerDown)
    }
  }, [open])

  // Keep the highlighted option inside the scrolled menu.
  useEffect(() => {
    if (!menuOpen || active < 0) return
    const node = optionRefs.current[active]
    if (node && typeof node.scrollIntoView === "function") {
      node.scrollIntoView({ block: "nearest" })
    }
  }, [menuOpen, active])

  /* ----- indicators ------------------------------------------------------ */

  function emit(next) {
    if (typeof onIndicatorsChange === "function") onIndicatorsChange(next)
  }

  function toggleFlag(key) {
    // Never mutate the incoming config — always hand back a fresh object.
    const next = { ...indicators }
    next[key] = !(indicators && indicators[key])
    emit(next)
  }

  function toggleEma(key, defaultPeriod) {
    const current = readEma(indicators, key, defaultPeriod)
    const next = { ...indicators }
    next[key] = { on: !current.on, period: current.period }
    emit(next)
  }

  function closePop() {
    setPeriodKey(null)
    setDraftPeriod("")
  }

  function togglePop(key, defaultPeriod) {
    if (periodKey === key) {
      closePop()
      return
    }
    // Only one popover is ever open, so opening one replaces the other.
    setPeriodKey(key)
    setDraftPeriod(String(readEma(indicators, key, defaultPeriod).period))
  }

  function applyPeriod(key, defaultPeriod) {
    const raw = String(draftPeriod).trim()
    const parsed = Number(raw)
    // Non-numeric input is discarded rather than written into the config.
    if (raw !== "" && Number.isFinite(parsed)) {
      const clamped = Math.min(MAX_PERIOD, Math.max(MIN_PERIOD, Math.round(parsed)))
      const current = readEma(indicators, key, defaultPeriod)
      const next = { ...indicators }
      next[key] = { on: current.on, period: clamped }
      emit(next)
    }
    closePop()
  }

  function handlePeriodKeyDown(event, key, defaultPeriod) {
    if (event.key === "Enter") {
      event.preventDefault()
      applyPeriod(key, defaultPeriod)
    } else if (event.key === "Escape") {
      event.preventDefault()
      closePop()
    }
  }

  // Escape and outside clicks dismiss the period popover.
  useEffect(() => {
    if (!periodKey) return undefined

    function onPointerDown(event) {
      if (listRef.current && !listRef.current.contains(event.target)) {
        setPeriodKey(null)
        setDraftPeriod("")
      }
    }
    function onKeyDown(event) {
      if (event.key === "Escape") {
        setPeriodKey(null)
        setDraftPeriod("")
      }
    }

    document.addEventListener("mousedown", onPointerDown)
    document.addEventListener("keydown", onKeyDown)
    return () => {
      document.removeEventListener("mousedown", onPointerDown)
      document.removeEventListener("keydown", onKeyDown)
    }
  }, [periodKey])

  // Send focus into the popover so it is immediately keyboard operable.
  useEffect(() => {
    if (!periodKey) return
    const node = periodInputRef.current
    if (node && typeof node.focus === "function") {
      node.focus()
      if (typeof node.select === "function") node.select()
    }
  }, [periodKey])

  /* ----- render ---------------------------------------------------------- */

  return (
    <div className="tech__rail-stack">
      {/* 1 — ticker combobox and the selected-stock card */}
      <div className="rail-group">
        <h2 className="rail-group__title">Select a stock</h2>
        <div className="rail-group__body">
          <div className="picker" ref={pickerRef}>
            <div className="picker__field">
              <Icon name="search" size={16} className="picker__icon" />
              <input
                className="picker__input"
                id={inputId}
                type="text"
                role="combobox"
                autoComplete="off"
                placeholder="Search 14 tickers…"
                aria-label="Search tickers"
                aria-expanded={menuOpen}
                aria-controls={listId}
                aria-autocomplete="list"
                aria-activedescendant={
                  menuOpen && active >= 0 ? optionId(active) : undefined
                }
                value={query}
                onChange={handleQueryChange}
                onFocus={() => setOpen(true)}
                onKeyDown={handleInputKeyDown}
              />
            </div>

            {menuOpen && (
              <div className="picker__menu" id={listId} role="listbox" aria-label="Tickers">
                {matches.map((item, index) => (
                  <button
                    key={item.symbol}
                    id={optionId(index)}
                    type="button"
                    role="option"
                    aria-selected={item.symbol === symbol}
                    tabIndex={-1}
                    className={
                      index === active
                        ? "picker__option picker__option--active"
                        : "picker__option"
                    }
                    ref={node => {
                      optionRefs.current[index] = node
                    }}
                    // Keep focus in the input so the click lands before any blur.
                    onMouseDown={event => event.preventDefault()}
                    onMouseEnter={() => setActiveIndex(index)}
                    onClick={() => selectSymbol(item.symbol)}
                  >
                    <span className="picker__option-mark">
                      <TickerMark symbol={item.symbol} size={24} />
                    </span>
                    <span className="picker__option-text">
                      <span className="picker__option-symbol">{item.symbol}</span>
                      <span className="picker__option-name">{item.name}</span>
                    </span>
                  </button>
                ))}
              </div>
            )}

            {open && !hasMatches && (
              <div className="picker__menu">
                <p className="picker__empty">No matching tickers</p>
              </div>
            )}
          </div>

          <div className="selected">
            <div className="selected__head">
              <TickerMark symbol={symbol} size={40} />
              <div className="selected__text">
                <span className="selected__symbol">{symbol || "—"}</span>
                <span className="selected__name">{company ? company.name : "—"}</span>
              </div>
            </div>
            <div className="selected__figures">
              <span className="selected__price">{money(company ? company.price : null)}</span>
              <Delta value={session ? session.changePct : null} percent />
            </div>
          </div>
        </div>
      </div>

      {/* 2 — timeframe */}
      <div className="rail-group">
        <h2 className="rail-group__title">Timeframe</h2>
        <div className="rail-group__body">
          <SegmentedControl
            options={TIMEFRAMES}
            value={timeframe}
            onChange={onTimeframeChange}
            ariaLabel="Select timeframe"
          />
        </div>
      </div>

      {/* 3 — indicators */}
      <div className="rail-group">
        <h2 className="rail-group__title">Technical indicators</h2>
        <div className="rail-group__body">
          <div className="indicator-list" ref={listRef}>
            {INDICATOR_ROWS.map(row => {
              const isEma = row.kind === "ema"
              const ema = isEma ? readEma(indicators, row.key, row.defaultPeriod) : null
              // The label tracks the live period, so EMA (9) becomes EMA (12).
              const label = isEma ? "EMA (" + ema.period + ")" : row.label
              const checked = isEma ? ema.on : !!(indicators && indicators[row.key])
              const popOpen = periodKey === row.key

              return (
                <div className="indicator-row" key={row.key}>
                  <div className="indicator-row__main">
                    <Checkbox
                      id={"indicator-" + baseId + "-" + row.key}
                      checked={checked}
                      onChange={() =>
                        isEma ? toggleEma(row.key, row.defaultPeriod) : toggleFlag(row.key)
                      }
                      ariaLabel={label}
                      label={
                        <>
                          {row.swatch ? (
                            <span
                              className="indicator-swatch"
                              style={{ background: row.swatch }}
                              aria-hidden="true"
                            />
                          ) : null}
                          {label}
                        </>
                      }
                    />
                  </div>

                  {isEma && (
                    <button
                      type="button"
                      className="indicator-row__gear"
                      aria-label={"Change " + label + " period"}
                      aria-haspopup="dialog"
                      aria-expanded={popOpen}
                      aria-controls={popOpen ? popId : undefined}
                      onClick={() => togglePop(row.key, row.defaultPeriod)}
                    >
                      <Icon name="sortDesc" size={14} />
                    </button>
                  )}

                  {isEma && popOpen && (
                    <div
                      className="indicator-pop"
                      id={popId}
                      role="dialog"
                      aria-label={label + " period"}
                    >
                      <p className="indicator-pop__title">Period</p>
                      <div className="indicator-pop__row">
                        <input
                          className="indicator-pop__input"
                          ref={periodInputRef}
                          type="number"
                          inputMode="numeric"
                          min={MIN_PERIOD}
                          max={MAX_PERIOD}
                          step="1"
                          aria-label={label + " period, between 2 and 400"}
                          value={draftPeriod}
                          onChange={event => setDraftPeriod(event.target.value)}
                          onKeyDown={event =>
                            handlePeriodKeyDown(event, row.key, row.defaultPeriod)
                          }
                        />
                      </div>
                      <div className="indicator-pop__actions">
                        <button type="button" className="btn btn--ghost btn--sm" onClick={closePop}>
                          Cancel
                        </button>
                        <button
                          type="button"
                          className="btn btn--primary btn--sm"
                          onClick={() => applyPeriod(row.key, row.defaultPeriod)}
                        >
                          Apply
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>

          {/*
            Intentionally inert in the prototype: "Add indicator" is a visual
            affordance for the future indicator catalogue and carries no handler.
          */}
          <button type="button" className="btn btn--ghost" style={FULL_WIDTH}>
            <Icon name="plus" size={16} className="btn__icon" />
            Add indicator
          </button>
        </div>
      </div>

      {/* 4 — chart style */}
      <div className="rail-group">
        <h2 className="rail-group__title">Chart style</h2>
        <div className="rail-group__body">
          <SegmentedControl
            options={CHART_STYLES}
            value={chartStyle}
            onChange={onChartStyleChange}
            ariaLabel="Select chart style"
          />
        </div>
      </div>

      {/*
        5 — every control above already applies immediately, so this button is a
        reassurance affordance rather than the thing that makes the chart update.
      */}
      <div className="rail-group">
        <div className="rail-group__body">
          <button type="button" className="btn btn--primary" style={FULL_WIDTH} onClick={onUpdate}>
            Update chart
          </button>
        </div>
      </div>
    </div>
  )
}
