import React, { useEffect, useRef } from "react"

/**
 * The four-pane technical chart: price, volume, RSI and MACD.
 *
 * GATSBY CONSTRAINT — the whole reason this file is shaped the way it is:
 * lightweight-charts touches `window` at import time, and Gatsby renders every
 * page to static HTML in Node at build time. A top-level
 * `import "lightweight-charts"` breaks `gatsby build` outright. So the library
 * is pulled in with a dynamic `await import()` INSIDE useEffect, which only ever
 * runs in the browser. The server renders empty, correctly-sized panes and the
 * charts mount on hydration. This applies to every pane here, not just the main
 * one — there is no sub-panel exemption.
 *
 * HOW THE PANES STAY IN LOCK-STEP
 * lightweight-charts v4 has no native multi-pane support, so each pane is its
 * own chart instance and three things are synchronised by hand:
 *
 *  1. Horizontal alignment. Every pane pins `rightPriceScale.minimumWidth` to
 *     the same value. Without it each pane sizes its price gutter to its own
 *     labels — "195.42" and "72" are different widths — and the panes drift out
 *     of vertical alignment by a few pixels.
 *
 *  2. Time range. Panes sync through `subscribeVisibleLogicalRangeChange`, which
 *     works in LOGICAL INDEX space. That is only equivalent across panes if every
 *     pane holds exactly one point per bar, so series that start late (an EMA is
 *     undefined for its first `period` bars) are padded with WHITESPACE points
 *     `{ time }` rather than being filtered down to a shorter array. Filtering
 *     would silently shift every pane's index space apart.
 *
 *  3. Crosshair. Each pane broadcasts its hovered time to the others, which place
 *     their own crosshair at their own series' value for that time. A `syncing`
 *     flag breaks the feedback loop the broadcast would otherwise cause.
 */

/** Pane heights, in CSS pixels. */
export const PANE_HEIGHTS = { main: 420, volume: 90, rsi: 120, macd: 140 }

/** Shared price-gutter width — see note 1 above. */
const PRICE_SCALE_WIDTH = 68

/**
 * The RSI pane is pinned to a fixed 0-100 scale so the 30/70 band can be drawn
 * as a CSS overlay at a known position. These two constants are the single
 * source of that geometry: change the margin and the band follows.
 */
const RSI_MARGIN = 0.08
const rsiOffset = value => RSI_MARGIN + (1 - value / 100) * (1 - RSI_MARGIN * 2)

// Rounded so the serialised style attribute reads "33.6%" rather than a
// floating-point tail like "33.599999999999994%".
const round2 = n => Math.round(n * 100) / 100

export const RSI_BAND_TOP = round2(rsiOffset(70) * 100)
export const RSI_BAND_HEIGHT = round2((rsiOffset(30) - rsiOffset(70)) * 100)

function readToken(styles, name) {
  const value = styles.getPropertyValue(name)
  return value && value.trim() ? value.trim() : undefined
}

/** Drops undefined keys so lightweight-charts falls back to its own defaults. */
function defined(object) {
  const out = {}
  for (const key of Object.keys(object)) {
    if (object[key] !== undefined) out[key] = object[key]
  }
  return out
}

/**
 * Aligns a null-padded indicator array to the candle array, emitting whitespace
 * points where the indicator is undefined. See note 2 above.
 */
function toLineData(candles, values) {
  const out = new Array(candles.length)
  for (let i = 0; i < candles.length; i += 1) {
    const v = values ? values[i] : null
    out[i] = v === null || v === undefined ? { time: candles[i].time } : { time: candles[i].time, value: v }
  }
  return out
}

/** time -> value, so a pane can place its crosshair at its own series value. */
function toValueMap(data) {
  const map = new Map()
  for (const point of data) {
    if (point.value !== undefined) map.set(point.time, point.value)
  }
  return map
}

export default function ChartStack({ view, chartStyle = "candlestick", intraday = false }) {
  const mainRef = useRef(null)
  const volumeRef = useRef(null)
  const rsiRef = useRef(null)
  const macdRef = useRef(null)

  const { candles, overlays, showVolume, showRsi, showMacd } = view

  useEffect(() => {
    let charts = []
    let cancelled = false
    let observer = null
    let syncing = false

    async function mount() {
      if (!candles || !candles.length || !mainRef.current) return

      const lib = await import("lightweight-charts")
      // The component may have unmounted while the chunk was in flight.
      if (cancelled || !mainRef.current) return

      const { createChart, LineStyle, CrosshairMode } = lib
      const styles = window.getComputedStyle(document.documentElement)

      const grid = readToken(styles, "--chart-grid")
      const axis = readToken(styles, "--chart-axis")
      const crosshair = readToken(styles, "--chart-crosshair")
      const surface = readToken(styles, "--surface")
      const up = readToken(styles, "--chart-up")
      const down = readToken(styles, "--chart-down")
      const guide = readToken(styles, "--chart-guide")
      const fontFamily = readToken(styles, "--font-ui")

      // Which pane is last decides who draws the time axis.
      const panes = [
        { key: "main", ref: mainRef, height: PANE_HEIGHTS.main },
        showVolume ? { key: "volume", ref: volumeRef, height: PANE_HEIGHTS.volume } : null,
        showRsi ? { key: "rsi", ref: rsiRef, height: PANE_HEIGHTS.rsi } : null,
        showMacd ? { key: "macd", ref: macdRef, height: PANE_HEIGHTS.macd } : null,
      ].filter(pane => pane && pane.ref.current)

      if (!panes.length) return
      const lastKey = panes[panes.length - 1].key

      function baseOptions(pane) {
        return {
          width: pane.ref.current.clientWidth,
          height: pane.height,
          layout: {
            background: defined({ color: surface }),
            ...defined({ textColor: axis, fontFamily }),
            fontSize: 11,
            attributionLogo: false,
          },
          grid: {
            vertLines: { ...defined({ color: grid }), style: LineStyle.Solid },
            horzLines: { ...defined({ color: grid }), style: LineStyle.Solid },
          },
          rightPriceScale: {
            borderVisible: false,
            minimumWidth: PRICE_SCALE_WIDTH,
            scaleMargins: { top: 0.1, bottom: 0.1 },
          },
          timeScale: {
            borderVisible: false,
            visible: pane.key === lastKey,
            timeVisible: intraday,
            secondsVisible: false,
            rightOffset: 2,
          },
          crosshair: {
            mode: CrosshairMode.Normal,
            vertLine: {
              ...defined({ color: crosshair, labelBackgroundColor: axis }),
              width: 1,
              style: LineStyle.Dashed,
              labelVisible: pane.key === lastKey,
            },
            horzLine: {
              ...defined({ color: crosshair, labelBackgroundColor: axis }),
              width: 1,
              style: LineStyle.Dashed,
            },
          },
          handleScale: { axisPressedMouseMove: false },
          localization: { locale: "en-US" },
        }
      }

      // ---- Main pane: price plus the overlay lines -----------------------
      const mainPane = panes[0]
      const mainChart = createChart(mainPane.ref.current, baseOptions(mainPane))

      let priceSeries
      const closeLine = candles.map(c => ({ time: c.time, value: c.close }))
      if (chartStyle === "line") {
        priceSeries = mainChart.addLineSeries({
          ...defined({ color: readToken(styles, "--chart-line") }),
          lineWidth: 2,
          priceLineVisible: false,
        })
        priceSeries.setData(closeLine)
      } else if (chartStyle === "area") {
        priceSeries = mainChart.addAreaSeries({
          ...defined({
            lineColor: readToken(styles, "--chart-line"),
            topColor: readToken(styles, "--chart-area-top"),
            bottomColor: readToken(styles, "--chart-area-bottom"),
          }),
          lineWidth: 2,
          priceLineVisible: false,
        })
        priceSeries.setData(closeLine)
      } else {
        priceSeries = mainChart.addCandlestickSeries({
          ...defined({
            upColor: up,
            downColor: down,
            borderUpColor: up,
            borderDownColor: down,
            wickUpColor: up,
            wickDownColor: down,
          }),
          priceLineVisible: false,
        })
        priceSeries.setData(candles)
      }

      for (const overlay of overlays) {
        const series = mainChart.addLineSeries({
          ...defined({ color: readToken(styles, overlay.token) }),
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: false,
          crosshairMarkerVisible: false,
        })
        series.setData(toLineData(candles, overlay.values))
      }

      charts.push({
        key: "main",
        chart: mainChart,
        series: priceSeries,
        values: toValueMap(closeLine),
        container: mainPane.ref.current,
      })

      // ---- Volume ---------------------------------------------------------
      const volumePane = panes.find(p => p.key === "volume")
      if (volumePane) {
        const chart = createChart(volumePane.ref.current, baseOptions(volumePane))
        const series = chart.addHistogramSeries({
          priceLineVisible: false,
          lastValueVisible: false,
          priceFormat: { type: "volume" },
        })
        const volUp = readToken(styles, "--chart-vol-up")
        const volDown = readToken(styles, "--chart-vol-down")
        series.setData(
          candles.map(c => ({
            time: c.time,
            value: c.volume,
            ...defined({ color: c.close >= c.open ? volUp : volDown }),
          }))
        )
        charts.push({
          key: "volume",
          chart,
          series,
          values: toValueMap(candles.map(c => ({ time: c.time, value: c.volume }))),
          container: volumePane.ref.current,
        })
      }

      // ---- RSI ------------------------------------------------------------
      const rsiPane = panes.find(p => p.key === "rsi")
      if (rsiPane) {
        const options = baseOptions(rsiPane)
        options.rightPriceScale.scaleMargins = { top: RSI_MARGIN, bottom: RSI_MARGIN }
        const chart = createChart(rsiPane.ref.current, options)
        const series = chart.addLineSeries({
          ...defined({ color: readToken(styles, "--chart-line") }),
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: true,
          // Pinning 0-100 is what makes the CSS band overlay land exactly on
          // the 30 and 70 guides.
          autoscaleInfoProvider: () => ({ priceRange: { minValue: 0, maxValue: 100 } }),
        })
        const data = toLineData(candles, view.rsi)
        series.setData(data)
        for (const level of [70, 30]) {
          series.createPriceLine({
            price: level,
            ...defined({ color: guide }),
            lineWidth: 1,
            lineStyle: LineStyle.Dashed,
            axisLabelVisible: true,
            title: "",
          })
        }
        charts.push({
          key: "rsi",
          chart,
          series,
          values: toValueMap(data),
          container: rsiPane.ref.current,
        })
      }

      // ---- MACD -----------------------------------------------------------
      const macdPane = panes.find(p => p.key === "macd")
      if (macdPane) {
        const chart = createChart(macdPane.ref.current, baseOptions(macdPane))

        const histogram = chart.addHistogramSeries({
          priceLineVisible: false,
          lastValueVisible: false,
        })
        const histUp = readToken(styles, "--chart-vol-up")
        const histDown = readToken(styles, "--chart-vol-down")
        histogram.setData(
          candles.map((c, i) => {
            const v = view.macd.histogram[i]
            if (v === null || v === undefined) return { time: c.time }
            return { time: c.time, value: v, ...defined({ color: v >= 0 ? histUp : histDown }) }
          })
        )

        const macdLine = chart.addLineSeries({
          ...defined({ color: readToken(styles, "--chart-macd") }),
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: false,
        })
        const macdData = toLineData(candles, view.macd.macd)
        macdLine.setData(macdData)

        const signalLine = chart.addLineSeries({
          ...defined({ color: readToken(styles, "--chart-macd-signal") }),
          lineWidth: 2,
          priceLineVisible: false,
          lastValueVisible: false,
        })
        signalLine.setData(toLineData(candles, view.macd.signal))

        charts.push({
          key: "macd",
          chart,
          series: macdLine,
          values: toValueMap(macdData),
          container: macdPane.ref.current,
        })
      }

      // ---- Synchronise time range and crosshair ---------------------------
      for (const entry of charts) {
        entry.chart.timeScale().subscribeVisibleLogicalRangeChange(range => {
          if (syncing || !range) return
          syncing = true
          for (const other of charts) {
            if (other !== entry) other.chart.timeScale().setVisibleLogicalRange(range)
          }
          syncing = false
        })

        entry.chart.subscribeCrosshairMove(param => {
          if (syncing) return
          syncing = true
          for (const other of charts) {
            if (other === entry) continue
            if (param.time === undefined) {
              other.chart.clearCrosshairPosition()
            } else {
              const value = other.values.get(param.time)
              if (value !== undefined) {
                other.chart.setCrosshairPosition(value, param.time, other.series)
              } else {
                other.chart.clearCrosshairPosition()
              }
            }
          }
          syncing = false
        })
      }

      charts[0].chart.timeScale().fitContent()

      // Resize every pane together off the main pane's width.
      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(entries => {
          if (!entries.length) return
          const width = Math.floor(entries[0].contentRect.width)
          for (const entry of charts) entry.chart.applyOptions({ width })
        })
        observer.observe(charts[0].container)
      }
    }

    mount()

    return () => {
      cancelled = true
      if (observer) observer.disconnect()
      for (const entry of charts) entry.chart.remove()
      charts = []
    }
  }, [candles, overlays, view, chartStyle, intraday, showVolume, showRsi, showMacd])

  return (
    <div className="chart-stack">
      <div className="chart-pane chart-pane--main">
        <div className="chart-pane__canvas" ref={mainRef} style={{ height: PANE_HEIGHTS.main + "px" }} />
      </div>

      {showVolume && (
        <div className="chart-pane">
          <span className="chart-pane__label">Volume</span>
          <div className="chart-pane__canvas" ref={volumeRef} style={{ height: PANE_HEIGHTS.volume + "px" }} />
        </div>
      )}

      {showRsi && (
        <div className="chart-pane">
          <span className="chart-pane__label">RSI (14)</span>
          <div className="chart-pane__canvas" ref={rsiRef} style={{ height: PANE_HEIGHTS.rsi + "px" }}>
            {/* The 30-70 band. The RSI pane is pinned to a fixed 0-100 scale,
                so these offsets land exactly on the dashed guides. */}
            <span
              className="rsi-band"
              style={{ top: RSI_BAND_TOP + "%", height: RSI_BAND_HEIGHT + "%" }}
              aria-hidden="true"
            />
          </div>
        </div>
      )}

      {showMacd && (
        <div className="chart-pane">
          <span className="chart-pane__label">MACD (12, 26, 9)</span>
          <div className="chart-pane__canvas" ref={macdRef} style={{ height: PANE_HEIGHTS.macd + "px" }} />
        </div>
      )}
    </div>
  )
}
